// Ambil pesan dari request dan normalisasi
const msg = ($input.first().json.body && $input.first().json.body.message) ? String($input.first().json.body.message) : '';
const rawLow = msg.toLowerCase().trim();

// Normalisasi typo & singkatan umum calon mahasiswa
let norm = rawLow
  .replace(/\bbya\b/g, 'biaya')
  .replace(/\bkulah\b/g, 'kuliah')
  .replace(/\bsmster\b/g, 'semester')
  .replace(/\bsmt\b/g, 'semester')
  .replace(/\bbrp\b/g, 'berapa')
  .replace(/\bdpt\b|\bdapet\b/g, 'dapat')
  .replace(/\bcepet\b/g, 'cepat')
  .replace(/\bkrj\b/g, 'kerja')
  .replace(/\bmatkul\b|\bmk\b/g, 'mata kuliah')
  .replace(/\bkaprodi\b/g, 'ketua prodi')
  .replace(/\bjurusan\b/g, 'program studi');

// -----------------------------------------------------------------------------
// 1. SECURITY, PRIVACY & OUT-OF-SCOPE GUARD (DETERMINISTIC PRE-CHECK)
// -----------------------------------------------------------------------------
let privacy_action = 'NONE';
let refusal_message = '';

const hasCypherInjection =
  /\b(detach\s+delete|drop\s+(constraint|index|database)|call\s+(db|dbms|apoc)|load\s+csv|union\s+select)\b/i.test(rawLow) ||
  /\b(match|create|merge)\s*\(/i.test(rawLow) ||
  /\bwith\s+\w+\s+match\b/i.test(rawLow) ||
  /('\s*or\s+1\s*=\s*1|;\s*(match|create|merge|delete|set)\b|--\s*$)/i.test(rawLow);

const hasPIIRequest =
  /\b(gaji|penghasilan|nomor\s*hp|no\s*hp|telepon\s*pribadi|alamat\s*rumah|nim\b|identitas\s*alumni|mahasiswa\s*yang\s*tidak\s*lulus)\b/i.test(norm) ||
  /\b(?:daftar\s+)?nama(?:\s+\w+){0,2}\s+(alumni|lulusan|mahasiswa|responden)\b/i.test(norm) ||
  /\b(siapa\s+(?:saja\s+)?nama|siapa\s+saja)\b[^\n]{0,45}\b(alumni|lulusan|mahasiswa|responden|1\s*orang)\b/i.test(norm);

const hasDifferencing =
  /\b(selisih|dikurangi|minus|kecuali|selain)\b/i.test(norm) &&
  /\b(tracer|responden|lulusan|dp|desain\s*produk|total)\b/i.test(norm);

const hasExternalUni =
  /\b(universitas\s+indonesia|itb|ugm|ipb|its|undip|unpad|binus|trisakti|untar|uph)\b/i.test(norm) ||
  (/\bui\b/i.test(norm) && !/\bupj\b/i.test(norm) && /\bkedokteran|biaya|kuliah\b/i.test(norm));

const hasNonUpjProgram =
  /\b(kedokteran|teknik\s+nuklir|farmasi|ilmu\s+hukum|keperawatan|peternakan|pertanian|astronomi|antropologi)\b/i.test(norm);

// -----------------------------------------------------------------------------
// 2. ENTITY & SLOT EXTRACTION (PRODI, FAKULTAS, TAHUN, SEMESTER)
// -----------------------------------------------------------------------------
const prodiAliases = [
  { code: 'INF', pats: [/\binformatika\b/, /\binf\b/] },
  { code: 'SIF', pats: [/\bsistem\s+informasi\b/, /\bsif\b/, /\bsi\b/] },
  { code: 'AKT', pats: [/\bakuntansi\b/, /\bakt\b/] },
  { code: 'MNJ', pats: [/\bmanajemen\b/, /\bmnj\b/] },
  { code: 'PSI', pats: [/\bpsikologi\b/, /\bpsi\b/] },
  { code: 'KOM', pats: [/\bilmu\s+komunikasi\b/, /\bkomunikasi\b/, /\bkom\b/] },
  { code: 'DKV', pats: [/\bdesain\s+komunikasi\s+visual\b/, /\bdkv\b/] },
  { code: 'DP',  pats: [/\bdesain\s+produk\b/, /\bdp\b/] },
  { code: 'TSP', pats: [/\bteknik\s+sipil\b/, /\bsipil\b/, /\btsp\b/] },
  { code: 'ARS', pats: [/\barsitektur\b/, /\bars\b/] },
  { code: 'PPAR', pats: [/\bppar\b/, /\bprofesi\s+arsitek\b/] }
];

const prodi_codes = [];
for (const pa of prodiAliases) {
  if (pa.pats.some(rx => rx.test(norm))) {
    prodi_codes.push(pa.code);
  }
}

const faculty_codes = [];
if (/\bftd\b|fakultas\s+teknologi\s+dan\s+desain/.test(norm)) faculty_codes.push('FTD');
if (/\bfhb\b|fakultas\s+humaniora\s+dan\s+bisnis/.test(norm)) faculty_codes.push('FHB');

const yearMatches = norm.match(/\b(2022|2023|2024)\b/g) || [];
let years = [...new Set(yearMatches.map(y => parseInt(y, 10)))];
if (years.length === 2 && years.includes(2022) && years.includes(2024)) {
  years = [2022, 2023, 2024];
}

const semMatch = norm.match(/semester\s*(\d+)/);
const semStr = semMatch ? `Semester ${semMatch[1]}` : '';

// Small-cell suppression check for DP 2022 (n=2 < 5) or explicit n=1 sub-cell queries
const asksSmallCohortDP2022 =
  prodi_codes.includes('DP') && years.includes(2022) && /\b(tracer|waktu\s*tunggu|kesesuaian|detail|persen|alumni|kerja|responden)\b/.test(norm);
const asksSmallSubCell =
  /\b(n\s*=\s*[12]|1\s*orang\s*alumni|2\s*orang|sangat\s*erat\s*\(n=1\)|multinasional\s*\(n=1\))\b/i.test(norm);

if (hasCypherInjection) {
  privacy_action = 'REFUSE_SECURITY';
  refusal_message = 'Permintaan ditolak karena mengandung pola sintaks kueri yang tidak diizinkan. Silakan ajukan pertanyaan informasi akademik UPJ dalam bahasa alami.';
} else if (hasPIIRequest) {
  privacy_action = 'REFUSE_PII';
  refusal_message = 'Maaf, demi perlindungan privasi dan data pribadi, sistem tidak menyimpan maupun menampilkan data identitas personal, gaji individu alumni, NIM, nomor telepon pribadi, atau alamat rumah. Informasi publik yang tersedia hanya berupa rekapitulasi agregat program studi dan email institusional resmi (@upj.ac.id).';
} else if (hasDifferencing) {
  privacy_action = 'REFUSE_DIFFERENCING';
  refusal_message = 'Maaf, permintaan pengurangan atau isolasi selisih antar-kelompok untuk mengidentifikasi kelompok responden berukuran kecil (n < 5) ditolak sesuai kebijakan pengendalian pengungkapan data (disclosure control).';
} else if (hasExternalUni || (hasNonUpjProgram && prodi_codes.length === 0)) {
  privacy_action = 'REFUSE_OOS';
  refusal_message = 'Maaf, pertanyaan tersebut berada di luar cakupan informasi akademik dan tracer study Universitas Pembangunan Jaya (UPJ). Silakan tanyakan seputar 11 program studi, biaya, beasiswa, kurikulum, atau capaian lulusan UPJ.';
} else if (asksSmallCohortDP2022 || asksSmallSubCell) {
  privacy_action = 'SUPPRESS_SMALL_CELL';
  refusal_message = 'Sesuai kebijakan ambang privasi kelompok kecil (n >= 5), rincian persentase kohor atau sub-sel dengan jumlah responden kurang dari 5 orang (seperti kohor Desain Produk 2022 dengan n=2 atau sub-sel tunggal n=1) ditekan untuk mencegah risiko re-identifikasi. Data hanya dapat disajikan dalam bentuk agregasi tingkat fakultas (FTD) atau tingkat universitas (UPJ).';
}

// -----------------------------------------------------------------------------
// 3. INTENT CLASSIFICATION (SPECIFIC-FIRST, NO COLLISIONS)
// -----------------------------------------------------------------------------
const hasCourse =
  /\b(mata\s+kuliah|kurikulum|sks|jadwal\s+kuliah|perkuliahan)\b/.test(norm) ||
  (!!semStr && !/\b(biaya|spp|total|uang)\b[^\n]*semester\s*1\b|\bsemester\s*1\b[^\n]*\b(biaya|spp)\b/.test(norm));
const hasTracer =
  /\b(tracer|waktu\s+tunggu|cepat\s+kerja|dapat\s+kerja|capaian\s+kerja|kerja\s+selaras(?:nya)?|kerja\s+nasional(?:nya)?|kesesuaian|selaras(?:nya)?|linearitas|multinasional(?:nya)?|nasional(?:nya)?|lokal(?:nya)?|berwirausaha|lulusan(?:nya)?|responden|terlacak|keterlacakan|alumni|karir(?:nya)?|pekerjaan|prospek)\b/.test(norm);
const hasTuition = /\b(biaya(?:nya)?|ukt|spp(?:nya)?|bayar|harga|potongan|uang\s+masuk|uang\s+pangkal|cicil)\b/.test(norm);
const hasScholarship = /\b(beasiswa(?:nya)?|jaya\s*100|kip|asak|influencer)\b/.test(norm);
const hasLecturer = /\b(dosen(?:nya)?|pengajar|ketua\s+prodi|head\s+of\s+department|koordinator|pimpinan|prof)\b|\bdr\./.test(norm);
const hasSpecialization = /\b(peminatan(?:nya)?|konsentrasi(?:nya)?|spesialisasi)\b/.test(norm);
const hasRequirement = /\b(syarat(?:nya)?|buta\s+warna|portofolio|latar\s+belakang|ipa|smk)\b/.test(norm);
const hasFacility = /\b(fasilitas(?:nya)?|lab(?:nya)?|laboratorium(?:nya)?|studio)\b/.test(norm);
const hasFAQ = /\b(faq|ptn|uang\s+kembali|pengembalian|jaminan\s+kerja|keunikan)\b/.test(norm);
const hasProdiMetadata = /\b(akreditasi(?:nya)?|gelar(?:nya)?|durasi|masa\s+studi|fakultas(?:nya)?)\b/.test(norm);
const hasProdiInfo = hasProdiMetadata || /\b(program\s+studi|prodi)\b/.test(norm);
const hasJalur = /\b(jalur(?:nya)?|rapor|usm|pendaftaran|cara\s+mendaftar|mendaftarnya)\b/.test(norm);

const isMultiIntent =
  (hasTracer && (hasCourse || hasFacility || hasRequirement || hasSpecialization || hasTuition || hasLecturer || hasProdiMetadata)) ||
  (hasCourse && (hasLecturer || hasFacility || hasSpecialization || hasTuition)) ||
  (hasTuition && (hasScholarship || hasLecturer || hasRequirement || hasFacility || hasSpecialization)) ||
  (hasFacility && hasRequirement) ||
  (hasRequirement && hasSpecialization);

let intent = 'fallback';
let cypher = '';
let params = {};
let is_ambiguous = false;

if (privacy_action === 'REFUSE_SECURITY' || privacy_action === 'REFUSE_PII' || privacy_action === 'REFUSE_DIFFERENCING' || privacy_action === 'REFUSE_OOS') {
  intent = privacy_action.toLowerCase();
  cypher = 'RETURN $action AS privacy_action LIMIT 0';
  params = { action: privacy_action };
} else if (privacy_action === 'SUPPRESS_SMALL_CELL') {
  intent = 'privacy_suppress_aggregate';
  cypher = `
    MATCH (u:University {code: 'UPJ'})-[:HAS_TRACER_SUMMARY]->(s:TracerSummary)
    WHERE size($years) = 0 OR s.tahun IN $years
    RETURN s.id AS source_id, s.tahun AS tahun,
           s.total_lulusan AS upj_total_lulusan,
           s.total_terlacak AS upj_total_terlacak,
           s.persen_wt_kurang_6_bulan AS upj_persen_cepat_kerja,
           s.persen_kesesuaian_selaras AS upj_persen_selaras,
           'SUPPRESSED_COHORT_OR_SUBCELL_LT_5' AS privacy_note
    ORDER BY s.tahun
  `;
  params = { years: years.length ? years : [2022, 2023, 2024] };
} else if (isMultiIntent) {
  // Multi-intent & Multi-hop parameterized traversal anchored at University->Faculty->ProgramStudi
  intent = 'multi_hop_combined';
  cypher = `
    MATCH (u:University {code: 'UPJ'})-[:HAS_FACULTY]->(f:Faculty)-[:OFFERS_PROGRAM]->(p:ProgramStudi)
    WHERE (size($prodi_codes) = 0 OR p.code IN $prodi_codes)
      AND (size($faculty_codes) = 0 OR f.code IN $faculty_codes)
    OPTIONAL MATCH (p)-[:HAS_TUITION_FEE]->(bk:BiayaKuliah)
    RETURN u.name AS universitas,
           p.code AS kode, p.name AS prodi, f.code AS fakultas_kode, f.name AS fakultas,
           p.degree AS gelar, p.akreditasi AS akreditasi,
           bk.total_semester_1 AS biaya_sem_1,
           bk.spp AS spp,
           [(p)-[:HAS_REQUIREMENT]->(req:SyaratKhusus) | {syarat_khusus: req.syarat_khusus, latar_belakang: req.latar_belakang}] AS syarat_khusus,
           [(p)-[:HAS_SPECIALIZATION]->(sp:Peminatan) | sp.name] AS peminatan,
           [(p)-[:HAS_FACILITY]->(fac:Facility) | fac.name][..10] AS fasilitas,
           [(p)-[:OFFERS_COURSE]->(c:Course) WHERE $sem = '' OR c.semester = $sem | c.semester + ': ' + c.name][..20] AS mata_kuliah,
           [(l:Lecturer)-[:TEACHES_IN]->(p) | l.name + ' (' + l.role + ' - ' + coalesce(l.email, '') + ')'][..8] AS dosen,
           [(p)-[:LEADS_TO_CAREER]->(car:CareerPath) | car.name][..10] AS prospek_karir,
           [(u)-[:OFFERS_SCHOLARSHIP]->(bs:Beasiswa) | {nama: bs.nama, syarat: bs.syarat}] AS beasiswa,
           [(p)-[:HAS_TRACER_STUDY]->(ts:TracerStudy) WHERE (size($years) = 0 OR ts.tahun IN $years) AND ts.jumlah_terlacak >= 5 | {
             id: ts.id,
             tahun: ts.tahun,
             lulusan: ts.jumlah_lulusan,
             terlacak: ts.jumlah_terlacak,
             wt_lt_6: CASE WHEN ts.wt_kurang_6_bulan < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.wt_kurang_6_bulan END,
             persen_cepat_kerja: CASE WHEN ts.wt_kurang_6_bulan < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_wt_kurang_6_bulan END,
             selaras: CASE WHEN ts.kesesuaian_selaras < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.kesesuaian_selaras END,
             persen_selaras: CASE WHEN ts.kesesuaian_selaras < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_kesesuaian_selaras END,
             lingkup_nasional: CASE WHEN ts.lingkup_nasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.lingkup_nasional END,
             persen_nasional: CASE WHEN ts.lingkup_nasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_lingkup_nasional END,
             lingkup_multinasional: CASE WHEN ts.lingkup_multinasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.lingkup_multinasional END,
             persen_multinasional: CASE WHEN ts.lingkup_multinasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_lingkup_multinasional END
           }] AS tracer_outcomes
    ORDER BY p.code
  `;
  params = { prodi_codes, faculty_codes, years, sem: semStr };
} else if (hasCourse) {
  intent = 'course_curriculum';
  cypher = `
    MATCH (p:ProgramStudi)-[:OFFERS_COURSE]->(c:Course)
    WHERE (size($prodi_codes) = 0 OR p.code IN $prodi_codes)
      AND ($sem = '' OR c.semester = $sem)
    RETURN p.code AS kode, p.name AS prodi, count(DISTINCT c) AS total_mata_kuliah,
           collect(DISTINCT c.semester + ': ' + c.name + ' (' + toString(c.sks) + ' SKS)')[..25] AS daftar_mata_kuliah
    ORDER BY p.code
  `;
  params = { prodi_codes, sem: semStr };
} else if (hasLecturer) {
  intent = 'lecturer_profile';
  cypher = `
    MATCH (l:Lecturer)-[:TEACHES_IN]->(p:ProgramStudi)
    WHERE size($prodi_codes) = 0 OR p.code IN $prodi_codes
    RETURN p.code AS kode, p.name AS prodi, l.name AS dosen, l.role AS jabatan, l.email AS email
    ORDER BY p.code, l.name
    LIMIT 30
  `;
  params = { prodi_codes };
} else if (hasTracer) {
  if (faculty_codes.length > 0 && prodi_codes.length === 0) {
    intent = 'tracer_faculty_comparison';
    cypher = `
      MATCH (f:Faculty)-[:OFFERS_PROGRAM]->(p:ProgramStudi)-[:HAS_TRACER_STUDY]->(ts:TracerStudy)
      WHERE f.code IN $faculty_codes AND (size($years) = 0 OR ts.tahun IN $years)
      RETURN f.code AS fakultas_kode, f.name AS fakultas, ts.tahun AS tahun,
             sum(ts.jumlah_lulusan) AS total_lulusan,
             sum(ts.jumlah_terlacak) AS total_terlacak,
             sum(ts.wt_kurang_6_bulan) AS total_wt_lt_6,
             sum(ts.kesesuaian_selaras) AS total_selaras
      ORDER BY ts.tahun, f.code
    `;
    params = { faculty_codes, years: years.length ? years : [2024] };
  } else if (prodi_codes.length > 0) {
    intent = 'tracer_prodi';
    cypher = `
      MATCH (p:ProgramStudi)
      WHERE p.code IN $prodi_codes
      OPTIONAL MATCH (p)-[:HAS_TRACER_STUDY]->(ts:TracerStudy)
        WHERE size($years) = 0 OR ts.tahun IN $years
      WITH p, ts
      ORDER BY p.code, ts.tahun
      RETURN p.code AS kode, p.name AS prodi, p.degree AS gelar,
             [(p)-[:LEADS_TO_CAREER]->(car:CareerPath) | car.name][..6] AS prospek_karir,
             collect(CASE
               WHEN ts IS NULL THEN null
               WHEN ts.jumlah_terlacak < 5 THEN {id: ts.id, tahun: ts.tahun, status: 'SUPPRESSED_COHORT_LT_5'}
               ELSE {
                 id: ts.id,
                 tahun: ts.tahun,
                 lulusan: ts.jumlah_lulusan,
                 terlacak: ts.jumlah_terlacak,
                 persen_terlacak: ts.persentase_terlacak,
                 wt_lt_6: CASE WHEN ts.wt_kurang_6_bulan < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.wt_kurang_6_bulan END,
                 persen_wt_lt_6: CASE WHEN ts.wt_kurang_6_bulan < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_wt_kurang_6_bulan END,
                 kesesuaian_selaras: CASE WHEN ts.kesesuaian_selaras < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.kesesuaian_selaras END,
                 persen_selaras: CASE WHEN ts.kesesuaian_selaras < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_kesesuaian_selaras END,
                 lingkup_lokal: 'EMPTY_IN_SOURCE_DATA (0)',
                 lingkup_nasional: CASE WHEN ts.lingkup_nasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.lingkup_nasional END,
                 persen_nasional: CASE WHEN ts.lingkup_nasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_lingkup_nasional END,
                 lingkup_multinasional: CASE WHEN ts.lingkup_multinasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.lingkup_multinasional END,
                 persen_multinasional: CASE WHEN ts.lingkup_multinasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_lingkup_multinasional END,
                 followed_by_tahun: [(ts)-[:FOLLOWED_BY]->(nxt:TracerStudy) | nxt.tahun],
                 sectors: [(ts)-[abs:ABSORBED_BY_SECTOR]->(lk:LingkupKerja) | {
                   kategori: lk.kategori,
                   jumlah: CASE WHEN abs.jumlah < 5 THEN 'SUPPRESSED_LT_5' ELSE abs.jumlah END
                 }]
               }
             END) AS tracer_records
      ORDER BY p.code
    `;
    params = { prodi_codes, years };
  } else {
    intent = 'tracer_university_summary';
    if (/\bprospek\s*kerjanya\s*bagus\b/.test(norm)) {
      is_ambiguous = true;
    }
    cypher = `
      MATCH (u:University {code: 'UPJ'})-[:HAS_TRACER_SUMMARY]->(s:TracerSummary)
      WHERE size($years) = 0 OR s.tahun IN $years
      RETURN s.id AS summary_id, s.tahun AS tahun,
             s.total_lulusan AS total_lulusan,
             s.total_terlacak AS total_terlacak,
             s.persentase_terlacak AS persen_terlacak,
             s.total_wt_kurang_6_bulan AS total_wt_lt_6,
             s.persen_wt_kurang_6_bulan AS persen_wt_lt_6,
             s.total_kesesuaian_selaras AS total_selaras,
             s.persen_kesesuaian_selaras AS persen_selaras,
             s.total_lingkup_nasional AS total_nasional,
             s.persen_lingkup_nasional AS persen_nasional,
             s.total_lingkup_multinasional AS total_multinasional,
             s.persen_lingkup_multinasional AS persen_multinasional,
             'Column_13_Lokal_Empty_In_Source_0' AS catatan_lokal,
             [(s)-[:INCLUDES_PRODI_TRACER]->(ts:TracerStudy) WHERE ts.jumlah_terlacak >= 5 | {
               prodi: ts.prodi_code,
               terlacak: ts.jumlah_terlacak,
               wt_lt_6: CASE WHEN ts.wt_kurang_6_bulan < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.wt_kurang_6_bulan END,
               persen_wt_lt_6: CASE WHEN ts.wt_kurang_6_bulan < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_wt_kurang_6_bulan END,
               selaras: CASE WHEN ts.kesesuaian_selaras < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.kesesuaian_selaras END,
               persen_selaras: CASE WHEN ts.kesesuaian_selaras < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.persen_kesesuaian_selaras END,
               nasional: CASE WHEN ts.lingkup_nasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.lingkup_nasional END,
               multinasional: CASE WHEN ts.lingkup_multinasional < 5 THEN 'SUPPRESSED_LT_5' ELSE ts.lingkup_multinasional END
             }] AS prodi_breakdown
      ORDER BY s.tahun
    `;
    params = { years };
  }
} else if (hasTuition) {
  if (/\b(potongan|rapor|uang\s+masuk)\b/.test(norm)) {
    intent = 'tuition_discount';
    cypher = `
      MATCH (u:University {code: 'UPJ'})
      RETURN u.potongan_uang_masuk_json AS potongan_uang_masuk,
             u.jalur_pendaftaran_json AS jalur_pendaftaran
    `;
    params = {};
  } else {
    intent = 'tuition_fee';
    if (prodi_codes.length === 0) is_ambiguous = true;
    cypher = `
      MATCH (p:ProgramStudi)-[:HAS_TUITION_FEE]->(b:BiayaKuliah)
      WHERE size($prodi_codes) = 0 OR p.code IN $prodi_codes
      RETURN p.code AS kode, p.name AS prodi, b.spp AS spp,
             b.sks_kelas AS sks_kelas, b.sks_praktik AS sks_praktik,
             b.total_semester_1 AS total_semester_1
      ORDER BY b.total_semester_1 ASC
    `;
    params = { prodi_codes };
  }
} else if (hasScholarship) {
  intent = 'scholarship';
  cypher = `
    MATCH (u:University {code: 'UPJ'})-[:OFFERS_SCHOLARSHIP]->(bs:Beasiswa)
    RETURN bs.nama AS nama_beasiswa, bs.syarat AS syarat
    ORDER BY bs.nama
  `;
  params = {};
} else if (hasSpecialization) {
  intent = 'specialization';
  cypher = `
    MATCH (p:ProgramStudi)-[:HAS_SPECIALIZATION]->(sp:Peminatan)
    WHERE size($prodi_codes) = 0 OR p.code IN $prodi_codes
    RETURN p.code AS kode, p.name AS prodi,
           collect(DISTINCT sp.name) AS peminatan,
           collect(DISTINCT sp.waktu_pemilihan)[0] AS waktu_pemilihan
    ORDER BY p.code
  `;
  params = { prodi_codes };
} else if (hasRequirement) {
  intent = 'special_requirement';
  cypher = `
    MATCH (p:ProgramStudi)-[:HAS_REQUIREMENT]->(sk:SyaratKhusus)
    WHERE size($prodi_codes) = 0 OR p.code IN $prodi_codes
    RETURN p.code AS kode, p.name AS prodi, sk.syarat_khusus AS syarat_khusus, sk.latar_belakang AS latar_belakang
    ORDER BY p.code
  `;
  params = { prodi_codes };
} else if (hasFAQ) {
  intent = 'faq';
  cypher = `
    MATCH (u:University {code: 'UPJ'})-[:HAS_FAQ]->(f:FAQ)
    RETURN f.pertanyaan AS pertanyaan, f.jawaban AS jawaban
  `;
  params = {};
} else if (hasFacility) {
  intent = 'facility';
  cypher = `
    MATCH (p:ProgramStudi)-[:HAS_FACILITY]->(f:Facility)
    WHERE size($prodi_codes) = 0 OR p.code IN $prodi_codes
    RETURN p.code AS kode, p.name AS prodi, collect(DISTINCT f.name) AS fasilitas
    ORDER BY p.code
  `;
  params = { prodi_codes };
} else if (hasProdiInfo) {
  intent = 'program_studi_info';
  cypher = `
    MATCH (f:Faculty)-[:OFFERS_PROGRAM]->(p:ProgramStudi)
    WHERE size($prodi_codes) = 0 OR p.code IN $prodi_codes
    RETURN f.code AS fakultas_kode, f.name AS fakultas, p.code AS kode, p.name AS prodi,
           p.akreditasi AS akreditasi, p.degree AS gelar, p.duration AS durasi
    ORDER BY f.code, p.code
  `;
  params = { prodi_codes };
} else if (hasJalur) {
  intent = 'admission_path';
  cypher = `
    MATCH (u:University {code: 'UPJ'})
    OPTIONAL MATCH (u)-[:OFFERS_SCHOLARSHIP]->(bs:Beasiswa)
    RETURN u.pmb_website AS website_pmb,
           u.jalur_pendaftaran_json AS jalur_pendaftaran,
           u.potongan_uang_masuk_json AS potongan_uang_masuk,
           collect(DISTINCT {nama: bs.nama, syarat: bs.syarat}) AS beasiswa
  `;
  params = {};
} else {
  intent = 'fallback_overview';
  is_ambiguous = true;
  cypher = `
    MATCH (u:University {code: 'UPJ'})
    OPTIONAL MATCH (u)-[:HAS_FACULTY]->(f:Faculty)-[:OFFERS_PROGRAM]->(p:ProgramStudi)
    OPTIONAL MATCH (u)-[:HAS_TRACER_SUMMARY]->(s:TracerSummary {tahun: 2024})
    RETURN u.name AS universitas, u.pmb_website AS website_pmb,
           collect(DISTINCT p.code + ' - ' + p.name + ' (' + p.akreditasi + ')') AS program_studi,
           s.persen_wt_kurang_6_bulan AS upj_2024_wt_lt_6_pct
    LIMIT 1
  `;
  params = {};
}

return [{
  json: {
    message: msg,
    normalized_message: norm,
    intent,
    prodi_codes,
    faculty_codes,
    years,
    privacy_action,
    refusal_message,
    is_ambiguous,
    cypher: cypher.trim(),
    params
  }
}];

// Ambil data dari Neo4j response dan metadata router
const neo4jResponse = $input.first().json;
const routerMeta = $('Build Cypher Query').first().json;
const message = routerMeta.message;
const intent = routerMeta.intent;
const privacy_action = routerMeta.privacy_action || 'NONE';
const refusal_message = routerMeta.refusal_message || '';
const is_ambiguous = !!routerMeta.is_ambiguous;

let contextObj = {
  intent,
  privacy_action,
  is_ambiguous,
  rows: []
};

try {
  const results = neo4jResponse.results || [];
  if (results.length > 0 && results[0].data && results[0].data.length > 0) {
    const columns = results[0].columns || [];
    contextObj.rows = results[0].data.map(d => {
      const obj = {};
      columns.forEach((col, i) => { obj[col] = d.row[i]; });
      return obj;
    });
  }
} catch (e) {
  contextObj.parse_error = e.message;
}

const contextText = contextObj.rows.length > 0
  ? JSON.stringify(contextObj, null, 2)
  : 'TIDAK ADA DATA DITEMUKAN DI KNOWLEDGE GRAPH.';

const prompt = `Kamu adalah asisten informasi resmi Universitas Pembangunan Jaya (UPJ).

Structured Evidence Payload (JSON dari Knowledge Graph Neo4j):
${contextText}

Pertanyaan Pengguna:
${message}

Aturan Ketat (Negative Constraints):
1. Jawab HANYA berdasarkan angka dan fakta eksplisit di dalam Structured Evidence Payload di atas. DILARANG mengarang atau mengekstrapolasi angka.
2. Jika suatu nilai tertulis "SUPPRESSED_LT_5", "SUPPRESSED_COHORT_LT_5", atau privacy_action aktif, sampaikan secara sopan bahwa rincian tersebut ditekan demi privasi kelompok kecil (n < 5) dan tampilkan data agregat universitas bila tersedia.
3. Jika is_ambiguous=true (mis. prodi belum disebutkan), minta klarifikasi prodi tujuan sambil menampilkan ringkasan rentang resmi yang ada pada payload.
4. Jika data kosong atau tertulis "EMPTY_IN_SOURCE_DATA", nyatakan secara jujur bahwa data tersebut tidak tercatat di sumber resmi dan arahkan ke pmb.upj.ac.id.
5. Jika pertanyaan berkaitan dengan hubungan mata kuliah dan tracer study, tegaskan bahwa data menunjukkan asosiasi tingkat program studi, bukan korelasi kausal individu.`;

return [{
  json: {
    message,
    intent,
    privacy_action,
    refusal_message,
    is_ambiguous,
    context: contextText,
    prompt
  }
}];

