const llmResponse = $input.first().json;
const fmt = $('Format Prompt').first().json;
const privacy_action = fmt.privacy_action || 'NONE';
const refusal_message = fmt.refusal_message || '';

// Deterministic enforcement for hard privacy/security/OOS blocks
if (['REFUSE_SECURITY', 'REFUSE_PII', 'REFUSE_DIFFERENCING', 'REFUSE_OOS'].includes(privacy_action) && refusal_message) {
  return [{
    json: {
      response: refusal_message,
      intent: fmt.intent,
      privacy_action,
      source: 'n8n_deterministic_guard'
    }
  }];
}

let responseText = 'Maaf, data yang diminta belum tersedia di basis pengetahuan UPJ. Silakan hubungi PMB UPJ di pmb.upj.ac.id.';

try {
  if (llmResponse.choices && llmResponse.choices.length > 0) {
    responseText = llmResponse.choices[0].message.content || responseText;
  } else if (llmResponse.error) {
    responseText = `Maaf, terjadi kendala pada layanan AI: ${llmResponse.error.message}. Silakan coba lagi.`;
  }
} catch (e) {
  responseText = 'Terjadi kesalahan teknis. Silakan hubungi PMB UPJ di pmb.upj.ac.id.';
}

if (privacy_action === 'SUPPRESS_SMALL_CELL' && refusal_message && !responseText.includes('n < 5') && !responseText.includes('privasi')) {
  responseText = `${refusal_message}\n\n${responseText}`;
}

return [{
  json: {
    response: responseText,
    intent: fmt.intent,
    privacy_action,
    source: 'n8n_sumopod_neo4j'
  }
}];
